class Solution:
    def shiftingLetters(self, s: str, shifts: list[list[int]]) -> str:
        n = len(s)
        diff = [0] * (n + 1)
        for start, end, direction in shifts:
            delta = 1 if direction == 1 else -1
            diff[start] += delta
            diff[end + 1] -= delta
        cur = 0
        res = []
        for i in range(n):
            cur += diff[i]
            shift = (ord(s[i]) - ord('a') + cur) % 26
            res.append(chr(ord('a') + shift))
        return "".join(res)

class Solution {
public:
    std::string shiftingLetters(std::string s, std::vector<std::vector<int>>& shifts) {
        int n = s.size();
        std::vector<int> diff(n + 1, 0);
        for (const auto& sh : shifts) {
            int delta = sh[2] == 1 ? 1 : -1;
            diff[sh[0]] += delta;
            diff[sh[1] + 1] -= delta;
        }
        int cur = 0;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            int shift = ((s[i] - 'a' + cur) % 26 + 26) % 26;
            s[i] = 'a' + shift;
        }
        return s;
    }
};

class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        int n = s.length();
        int[] diff = new int[n + 1];
        for (int[] sh : shifts) {
            int delta = sh[2] == 1 ? 1 : -1;
            diff[sh[0]] += delta;
            diff[sh[1] + 1] -= delta;
        }
        char[] chars = s.toCharArray();
        int cur = 0;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            int shift = ((chars[i] - 'a' + cur) % 26 + 26) % 26;
            chars[i] = (char) ('a' + shift);
        }
        return new String(chars);
    }
}

var shiftingLetters = function(s, shifts) {
    const n = s.length;
    const diff = new Int32Array(n + 1);
    for (const [start, end, dir] of shifts) {
        const delta = dir === 1 ? 1 : -1;
        diff[start] += delta;
        diff[end + 1] -= delta;
    }
    const res = new Array(n);
    let cur = 0;
    for (let i = 0; i < n; ++i) {
        cur += diff[i];
        const shift = ((s.charCodeAt(i) - 97 + cur) % 26 + 26) % 26;
        res[i] = String.fromCharCode(97 + shift);
    }
    return res.join('');
};
